import re
import sys
from .adaptation_versions import AdaptationVersions
from os import system, path
from .scfc import Scfc


class ScfcVersionValidator(object):
    def __init__(self, input_scfc_path, fixed_scfc_path, partition_source, enb_ip):
        self.input = input_scfc_path
        self.output = fixed_scfc_path
        self.partition_source = partition_source
        self.enb_ip = enb_ip

    def correct_version_value_in_scf_file(self):
        """Managed Object version value change in SCFC file based on AdaptationVersions file downloaded from eNB"""
        scfc = Scfc(self.input)
        self._create_directory_to_save_fixed_scfc(self.output)
        class_and_version = self._get_latest_class_versions_from_adaptation_versions_file(
            self.enb_ip, self.partition_source, self.output
        )
        self._fix_managed_objects_version(scfc, class_and_version, self.output)
        scfc.save(self.output)

    def _get_latest_class_versions_from_adaptation_versions_file(self, enb_ip, partition, output):
        adaptation_versions_path = self._collect_adaptation_versions_file_from_enb(
            self.enb_ip, self.partition_source, self.output
        )
        class_and_version = self._read_adaptation_version_file(adaptation_versions_path)
        return class_and_version

    def _collect_adaptation_versions_file_from_enb(self, enb_ip, partition, output):
        try:
            output_log_path = path.dirname(output)
            adaptation_versions_path = AdaptationVersions().get_from_enb(enb_ip, partition, output_dir=output_log_path)
        except IOError as e:
            print(("I/O error({0}): {1}".format(e.errno, e.strerror)))
        except Exception:
            print(("Unexpected error:", sys.exc_info()[0]))
        else:
            return adaptation_versions_path

    def _read_adaptation_version_file(self, path_to_file):
        class_and_version = self._read_file_with(path_to_file, '^.*name="([A-Za-z\.]+)".*version="([A-Za-z0-9_]+)".*$')
        return dict(class_and_version)

    def _read_file_with(self, path_to_file, reg_exp):
        class_and_version = {}
        end_of_version_mapping = '</adaptationVersionMapping>\n'
        try:
            with open(path_to_file, 'r') as adaptation_versions_file:
                for line in adaptation_versions_file.readlines():
                    if line == end_of_version_mapping:
                        break
                    matched = re.compile(reg_exp).match(line)
                    if matched:
                        class_and_version[matched.group(1)] = matched.group(2)
        except IOError as e:
            print(("I/O error({0}): {1}".format(e.errno, e.strerror)))
        except Exception:
            print(("Unexpected error:", sys.exc_info()[0]))
        return dict(class_and_version)

    def _fix_managed_objects_version(self, scfc, class_and_version, output_scfc_file):
        for managed_object_class in scfc.find_all_managed_objects():
            for dict_key in list(class_and_version.keys()):
                if managed_object_class.klass.split(':')[0] == str(dict_key):
                    managed_object_class.xml.attrib['version'] = class_and_version[dict_key]

    def _create_directory_to_save_fixed_scfc(self, output):
        folder_path = path.dirname(self.output)
        if not path.exists(folder_path):
            system('mkdir -p {}'.format(folder_path))
